#!/usr/bin/env python3
"""V48 selected club-history roster migration. Encoded to preserve Unicode and line endings."""
import base64, zlib
from pathlib import Path
compressed = ''
src = zlib.decompress(base64.b64decode(compressed)).decode('utf-8')
exec(compile(src, __file__, 'exec'), {'__name__': '__main__', '__file__': str(Path(__file__).resolve())})
